    rows = [12,18,24,30,36,42,48]
    cols = [11,17,23,29,35,41,47]
    out = {}
    for ri,r0 in enumerate(rows):
        for ci,c0 in enumerate(cols):
            if r0>=len(a) or c0>=len(a[0]): continue
            block = [a[r0+i][c0:c0+4] for i in range(4)]
            if all(row[0] in 'wW' for row in block) and all(row[3] in 'wW' for row in block):
