                flat = ''.join(block)
                if set(flat) <= {'w','W','S'}:
                    out[(ri,ci)] = 'absent:'+flat[:8]
                    continue
            from collections import Counter
            cnt = Counter(''.join(block))
            out[(ri,ci)] = ''.join(f'{k}{v}' for k,v in sorted(cnt.items()))
    return out
