{"code": "def panels(frame):
    seg=frame.segmentation
    cells=[]
    for n in seg['nodes']:
        if n['pixels']==16 and n['color'] in ('w','O'):
            b=n['boundary']
            r0=min(p[0] for p in b); c0=min(p[1] for p in b)
            if r0<2: continue
            cells.append((r0,c0,n['color']))
        elif n['color']=='N' and n['pixels']==12:
            b=n['boundary']
            r0=min(p[0] for p in b); c0=min(p[1] for p in b)
            cells.append((r0,c0,'N'))
    # group into panels by proximity
    cells.sort()
    groups=[]
    for c in cells:
        placed=False
        for g in groups:
            if abs(c[0]-g['r'][0])<10 and abs(c[1]-g['c'][0])<10:
                pass
        # simple: cluster by row/col sets
    # cluster via union-find on adjacency (rows within 6 and cols within 6)
    parent=list(range(len(cells)))
    def find(x):
        while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]
        return x
    def uni(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb: parent[ra]=rb
    for i in range(len(cells)):
        for j in range(i+1,len(cells)):
            if abs(cells[i][0]-cells[j][0])<=6 and abs(cells[i][1]-cells[j][1])<=6: uni(i,j)
    from collections import defaultdict
    d=defaultdict(list)
    for i,c in enumerate(cells): d[find(i)].append(c)
    out=[]
    for k,v in d.items():
        rows=sorted(set(x[0] for x in v)); cols=sorted(set(x[1] for x in v))
        out.append({'rows':rows,'cols':cols,'cells':v})
    for g in out:
        print('panel rows',g['rows'],'cols',g['cols'])
        for r in g['rows']:
            print('  ', ''.join(next((x[2] for x in g['cells'] if x[0]==r and x[1]==c), ' ') for c in g['cols']))
    return out
P = panels(current_frame)
"}

