{"code": "def board(frame):
    a = frame.ascii.split('\n')
    rows=[12,18,24,30,36,42,48]; cols=[11,17,23,29,35,41,47]
    valid=set(); empty=set(); pegs=set(); marks={}
    for ri,r0 in enumerate(rows):
        for ci,c0 in enumerate(cols):
            block=[a[r0+i][c0:c0+4] for i in range(4)]
            flat=''.join(block)
            s=set(flat)
            if s <= {'S','W'}: continue
            valid.add((ri,ci))
            if s=={'w'}: empty.add((ri,ci))
            elif 'N' in s: pegs.add((ri,ci))
            else: marks[(ri,ci)]=''.join(f'{k}{v}' for k,v in sorted({c:flat.count(c) for c in s}.items()))
    return valid,empty,pegs,marks
