            if abs(c[0]-g['r'][0])<10 and abs(c[1]-g['c'][0])<10:
                pass
        # simple: cluster by row/col sets
    # cluster via union-find on adjacency (rows within 6 and cols within 6)
    parent=list(range(len(cells)))
    def find(x):
        while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]
        return x
    def uni(a,b):
        ra,rb=find(a),find(b)
