    """Return dict: cell(r,c within panel) -> content, panels list with row/col coords."""
    seg=frame.segmentation
    raw=[]
    for n in seg['nodes']:
        if n['color']=='N' and n['pixels']==12:
            b=n['boundary']; raw.append((min(p[0] for p in b), min(p[1] for p in b), 'N'))
        elif n['pixels']==16 and n['color']=='w':
            b=n['boundary']; raw.append((min(p[0] for p in b), min(p[1] for p in b), 'w'))
        elif n['pixels']==16 and n['color']=='O':
            b=n['boundary']; raw.append((min(p[0] for p in b), min(p[1] for p in b), 'O'))
    # cluster
    parent=list(range(len(raw)))
    def find(x):
        while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]
        return x
    for i in range(len(raw)):
        for j in range(i+1,len(raw)):
            if abs(raw[i][0]-raw[j][0])<=6 and abs(raw[i][1]-raw[j][1])<=6:
                ra,rb=find(i),find(j)
                if ra!=rb: parent[ra]=rb
    from collections import defaultdict
    d=defaultdict(list)
    for i,c in enumerate(raw): d[find(i)].append(c)
    panels=[]
    for k,v in d.items():
        rows=sorted(set(x[0] for x in v)); cols=sorted(set(x[1] for x in v))
        grid={}
