from collections import deque
def solve(pegs):
    start=frozenset(pegs); seen={start}; q=deque([(start,())])
    best=(len(start),start,())
    while q:
        s,path=q.popleft()
        if len(s)<best[0]: best=(len(s),s,path)
        if len(s)==1: return path
        for (a,mid,b) in jumps(s):
            ns=frozenset((s-{a,mid})|{b})
            if ns not in seen:
                seen.add(ns); q.append((ns,path+((a,mid,b),)))
    return best[2],best[0]
