{"code": "def legal_jumps(panels):
    res=[]
    for pi,p in enumerate(panels):
        g=p['grid']
        pegs={k for k,v in g.items() if v[0]=='N'}
        cells=set(g)
        for (r,c) in pegs:
            for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
                mid=(r+dr,c+dc); land=(r+2*dr,c+2*dc)
                if mid in pegs and land in cells and land not in pegs:
                    res.append((pi,(r,c),mid,land))
    return res
def click_cell(panels, pi, cell):
